function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000000)) return 'Each value is an integer from 0 to 10^6.';
  if (!Number.isInteger(k) || k < 0 || k > 1000000) return 'k is an integer from 0 to 10^6.';
  return null;
}

