function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1500, 2000) : int(1, 8);
  const top = size === 'large' || rand() < 0.5 ? 1000000 : int(1, 16);
  const nums = Array.from({ length: n }, () => int(0, top));
  const mode = int(0, 3);
  let k;
  if (mode === 0) {
    // Already equal: no operation needed.
    k = nums.reduce((x, y) => x ^ y, 0);
    if (k > 1000000) k = int(0, 1000000);
  } else if (mode === 1) {
    k = int(0, 16);
  } else {
    k = int(0, 1000000);
  }
  return [nums, k];
}
